import { useState } from "react";
import { 
  Anchor, Ship, Compass, Gauge, FileText, Radio, Map, LayoutDashboard,
  Users, Building, Shield, Wrench, Package, Activity, AlertTriangle,
  BarChart3, Plug, Settings, ClipboardList, ChevronDown, User, Bell,
  LifeBuoy, Waves, Radar
} from "lucide-react";

// ---- Color palettes ----
const CURRENT = {
  primary: "#1677ff",
  primaryLight: "#e6f4ff",
  bg: "#ffffff",
  bgLayout: "#f5f5f5",
  border: "#f0f0f0",
  text: "#333333",
  textSecondary: "#8c8c8c",
};

const MARITIME = {
  primary: "#0d2b4e",
  primaryLight: "#e8f0f8",
  bg: "#ffffff",
  bgLayout: "#f0f3f7",
  border: "#e0e5ec",
  text: "#1a2332",
  textSecondary: "#5e6f82",
  accent: "#1a8fc9",
  accentLight: "#e5f4fb",
};

const sidebarItems = [
  { key: "home", icon: LayoutDashboard, label: "Trang chủ" },
  { key: "div1", divider: true },
  { key: "users", icon: Users, label: "Quản lý người dùng" },
  { key: "org", icon: Building, label: "Quản lý đơn vị" },
  { key: "roles", icon: Shield, label: "Phân quyền" },
  { key: "div2", divider: true },
  { key: "gis", icon: Map, label: "GIS • Bản đồ", children: 4 },
  { key: "div3", divider: true },
  { key: "beacon", icon: Wrench, label: "Báo hiệu hàng hải", children: 5 },
  { key: "asset", icon: Package, label: "Tài sản KCHTGT", children: 5 },
  { key: "movement", icon: Activity, label: "Biến động tài sản", children: 4 },
  { key: "docs", icon: FileText, label: "Văn bản & Sự cố", children: 3 },
  { key: "div4", divider: true },
  { key: "vts", icon: Gauge, label: "Khu nước & VTS", children: 5 },
  { key: "station", icon: Radio, label: "Đài duyên hải & Vệ tinh", children: 2 },
  { key: "div5", divider: true },
  { key: "reports", icon: BarChart3, label: "BÁO CÁO THỐNG KÊ", children: 9 },
  { key: "div6", divider: true },
  { key: "connections", icon: Plug, label: "Liên thông dữ liệu" },
  { key: "div7", divider: true },
  { key: "settings", icon: Settings, label: "Cấu hình hệ thống", disabled: true },
  { key: "logs", icon: ClipboardList, label: "Nhật ký hệ thống" },
];

// New icons for improved sidebar
const newIcons = {
  gis: Compass,
  beacon: LifeBuoy,
  asset: Anchor,
  movement: Activity,
  docs: AlertTriangle,
  vts: Radar,
  station: Radio,
  reports: BarChart3,
};

export default function App() {
  const [theme, setTheme] = useState<"current" | "maritime">("current");
  const palette = theme === "current" ? CURRENT : MARITIME;

  return (
    <div style={{ fontFamily: "-apple-system, sans-serif", height: "100vh", display: "flex", flexDirection: "column", background: palette.bgLayout }}>
      {/* ---- Top bar ---- */}
      <div style={{
        display: "flex", alignItems: "center", justifyContent: "space-between",
        padding: "8px 16px", background: "#fff", borderBottom: "1px solid #e8e8e8",
        gap: 12
      }}>
        <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
          <span style={{ fontWeight: 600, fontSize: 13, color: "#555" }}>UI Preview — So sánh giao diện</span>
        </div>
        <div style={{ display: "flex", gap: 4, background: "#f0f0f0", borderRadius: 6, padding: 2 }}>
          <button
            onClick={() => setTheme("current")}
            style={{
              padding: "5px 14px", borderRadius: 5, border: "none", cursor: "pointer",
              fontSize: 12, fontWeight: 600,
              background: theme === "current" ? "#1677ff" : "transparent",
              color: theme === "current" ? "#fff" : "#666",
            }}
          >
            Hiện tại
          </button>
          <button
            onClick={() => setTheme("maritime")}
            style={{
              padding: "5px 14px", borderRadius: 5, border: "none", cursor: "pointer",
              fontSize: 12, fontWeight: 600,
              background: theme === "maritime" ? "#0d2b4e" : "transparent",
              color: theme === "maritime" ? "#fff" : "#666",
            }}
          >
            Đề xuất
          </button>
        </div>
      </div>

      {/* ---- Main area ---- */}
      <div style={{ display: "flex", flex: 1, overflow: "hidden" }}>
        {/* ---- Sidebar ---- */}
        <div style={{
          width: 240, minWidth: 240, background: palette.bg,
          borderRight: `1px solid ${palette.border}`,
          display: "flex", flexDirection: "column",
          overflow: "hidden",
        }}>
          {/* Logo */}
          <div style={{
            height: 56, display: "flex", alignItems: "center", gap: 8,
            padding: "0 16px", borderBottom: `1px solid ${palette.border}`,
            cursor: "pointer",
          }}>
            {theme === "current" ? (
              <>
                <div style={{
                  width: 32, height: 32, borderRadius: 6,
                  background: palette.primary,
                  display: "flex", alignItems: "center", justifyContent: "center",
                }}>
                  <Users size={18} color="#fff" />
                </div>
                <span style={{ fontSize: 14, fontWeight: 700, color: palette.primary }}>Quản trị hệ thống</span>
              </>
            ) : (
              <>
                <div style={{
                  width: 36, height: 28, borderRadius: 3,
                  background: "#fff", border: "1px solid #d0d7e2",
                  display: "flex", alignItems: "center", justifyContent: "center",
                  overflow: "hidden",
                }}>
                  <Anchor size={18} color={palette.primary} />
                </div>
                <div style={{ display: "flex", flexDirection: "column", lineHeight: "1.2" }}>
                  <span style={{ fontSize: 12, fontWeight: 700, color: palette.primary }}>CỤC HÀNG HẢI</span>
                  <span style={{ fontSize: 10, color: palette.textSecondary }}>VIỆT NAM</span>
                </div>
              </>
            )}
          </div>

          {/* Menu items */}
          <div style={{ flex: 1, overflow: "auto", padding: "4px 0" }}>
            {sidebarItems.map((item) => {
              if (item.divider) {
                return <div key={item.key} style={{ height: 1, background: palette.border, margin: "4px 12px" }} />;
              }

              const isReports = item.key === "reports";
              const isDisabled = (item as any).disabled;
              const NewIcon = theme === "maritime" && (newIcons as any)[item.key]
                ? (newIcons as any)[item.key]
                : item.icon;

              return (
                <div
                  key={item.key}
                  style={{
                    display: "flex", alignItems: "center", gap: 10,
                    padding: "8px 16px", margin: "1px 8px", borderRadius: 6,
                    cursor: isDisabled ? "default" : "pointer",
                    color: isDisabled ? "#bbb" : (isReports ? "#999" : palette.text),
                    fontSize: 13,
                    fontWeight: isReports ? 600 : 400,
                    background: isReports ? "transparent" : "transparent",
                    opacity: isDisabled ? 0.5 : 1,
                    transition: "all 0.15s",
                    textTransform: isReports ? "uppercase" : "none",
                    letterSpacing: isReports ? "0.5px" : "normal",
                    fontSize: isReports ? 11 : 13,
                  }}
                  onMouseEnter={(e) => {
                    if (!isDisabled && !isReports) {
                      (e.currentTarget as HTMLElement).style.background = palette.primaryLight;
                      (e.currentTarget as HTMLElement).style.color = palette.primary;
                    }
                  }}
                  onMouseLeave={(e) => {
                    if (!isDisabled && !isReports) {
                      (e.currentTarget as HTMLElement).style.background = "transparent";
                      (e.currentTarget as HTMLElement).style.color = isReports ? "#999" : palette.text;
                    }
                  }}
                >
                  <NewIcon size={17} />
                  <span style={{ flex: 1 }}>{item.label}</span>
                  {item.children && <span style={{ fontSize: 10, color: palette.textSecondary, background: theme === "maritime" ? palette.accentLight : "#f0f0f0", padding: "1px 6px", borderRadius: 8 }}>{item.children}</span>}
                  {isDisabled && <span style={{ fontSize: 10, color: "#ccc", fontStyle: "italic" }}>sắp có</span>}
                </div>
              );
            })}
          </div>
        </div>

        {/* ---- Content mockup ---- */}
        <div style={{ flex: 1, padding: 20, overflow: "auto" }}>
          {/* Header bar */}
          <div style={{
            height: 48, background: "#fff", borderRadius: 8,
            display: "flex", alignItems: "center", justifyContent: "space-between",
            padding: "0 16px", marginBottom: 16,
            border: `1px solid ${palette.border}`,
          }}>
            <span style={{ fontWeight: 600, fontSize: 15, color: palette.text }}>Trang chủ</span>
            <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
              <Bell size={16} color={palette.textSecondary} />
              <div style={{
                width: 30, height: 30, borderRadius: "50%",
                background: palette.primary,
                display: "flex", alignItems: "center", justifyContent: "center",
              }}>
                <User size={16} color="#fff" />
              </div>
            </div>
          </div>

          {/* Welcome card */}
          <div style={{
            background: `linear-gradient(135deg, ${palette.primary} 0%, ${theme === "current" ? "#096dd9" : palette.accent} 100%)`,
            borderRadius: 10, padding: "20px 24px", color: "#fff", marginBottom: 16,
            boxShadow: `0 4px 12px ${palette.primary}33`,
          }}>
            <div style={{ fontSize: 20, fontWeight: 700, marginBottom: 4 }}>Chào buổi sáng, Nguyễn Văn A</div>
            <div style={{ fontSize: 14, opacity: 0.85 }}>Chào mừng bạn đến với Hệ thống Quản trị kết cấu hạ tầng giao thông đường thủy và hàng hải.</div>
          </div>

          {/* Stats row */}
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 12, marginBottom: 16 }}>
            {[
              { label: "Cảng biển", value: "48", icon: Anchor, color: palette.accent || palette.primary },
              { label: "Đèn biển", value: "85", icon: LifeBuoy, color: "#52c41a" },
              { label: "Luồng HH", value: "32", icon: Waves, color: "#fa8c16" },
            ].map((stat, i) => (
              <div key={i} style={{
                background: "#fff", borderRadius: 8, padding: "14px 16px",
                border: `1px solid ${palette.border}`,
                display: "flex", alignItems: "center", gap: 12,
              }}>
                <div style={{
                  width: 40, height: 40, borderRadius: 8,
                  background: `${stat.color}15`,
                  display: "flex", alignItems: "center", justifyContent: "center",
                }}>
                  <stat.icon size={20} color={stat.color} />
                </div>
                <div>
                  <div style={{ fontSize: 20, fontWeight: 700, color: palette.text }}>{stat.value}</div>
                  <div style={{ fontSize: 12, color: palette.textSecondary }}>{stat.label}</div>
                </div>
              </div>
            ))}
          </div>

          {/* Table mockup */}
          <div style={{
            background: "#fff", borderRadius: 8, padding: 16,
            border: `1px solid ${palette.border}`,
          }}>
            <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 12 }}>
              <span style={{ fontWeight: 600, fontSize: 14, color: palette.text }}>Danh sách cảng biển</span>
              <button style={{
                padding: "6px 14px", borderRadius: 6, border: "none",
                background: palette.primary, color: "#fff",
                fontSize: 12, fontWeight: 600, cursor: "pointer",
              }}>
                + Thêm mới
              </button>
            </div>
            <div style={{ display: "flex", flexDirection: "column", gap: 0 }}>
              {[
                ["Cảng Hải Phòng", "HPH", "Đang hoạt động"],
                ["Cảng Sài Gòn", "SGN", "Đang hoạt động"],
                ["Cảng Đà Nẵng", "DNG", "Bảo trì"],
              ].map((row, i) => (
                <div key={i} style={{
                  display: "grid", gridTemplateColumns: "2fr 1fr 1fr 80px",
                  padding: "10px 0", borderBottom: i < 2 ? `1px solid ${palette.border}` : "none",
                  fontSize: 13, color: palette.text,
                }}>
                  <span style={{ fontWeight: 500 }}>{row[0]}</span>
                  <span style={{ color: palette.textSecondary }}>{row[1]}</span>
                  <span>
                    <span style={{
                      background: row[2] === "Đang hoạt động" ? "#e6fffb" : "#fffbe6",
                      color: row[2] === "Đang hoạt động" ? "#08964c" : "#ad8b00",
                      padding: "2px 8px", borderRadius: 4, fontSize: 11, fontWeight: 600,
                    }}>
                      {row[2]}
                    </span>
                  </span>
                  <span style={{ color: palette.primary, cursor: "pointer", fontSize: 12 }}>Chi tiết →</span>
                </div>
              ))}
            </div>
          </div>

          {/* Color chips */}
          <div style={{ marginTop: 16, display: "flex", gap: 10, alignItems: "center" }}>
            <span style={{ fontSize: 12, color: palette.textSecondary }}>Palette:</span>
            {[palette.primary, palette.accent || palette.primary, "#52c41a", "#fa8c16"].map((c, i) => (
              <div key={i} style={{ width: 22, height: 22, borderRadius: 4, background: c, border: "1px solid rgba(0,0,0,0.1)" }} title={c} />
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}
